const raw = $input.first().json.content?.[0]?.text || '{}';
let p = {}; let parseError = false;
try { const c = raw.replace(/```json/gi,'').replace(/```/g,'').trim(); const m = c.match(/\{[\s\S]*\}/); p = JSON.parse(m?m[0]:c); }
catch(e) { parseError = true; p = {score:0,tier:'NEEDS_REVIEW',reasoning:'Scoring output could not be parsed',priority_action:'Manual review'}; }
let score = parseInt(p.score); if (isNaN(score)) score = 30; score = Math.max(0, Math.min(100, score));
let tier = String(p.tier||'').toUpperCase(); if (parseError) { tier = 'NEEDS_REVIEW'; } else if (!['HOT','WARM','COLD'].includes(tier)) { tier = score>=80?'HOT':score>=40?'WARM':'COLD'; }
function normPhone(x){ let d=String(x||'').replace(/\D/g,''); if(d.length===10) d='91'+d; else if(d.length===11 && d[0]==='0') d='91'+d.slice(1); return d?('+'+d):''; }
const s = $('Score Trigger').first().json.body || $('Score Trigger').first().json;
return [{json:{score,tier,reasoning:p.reasoning||'',priority_action:p.priority_action||'',lead_name:s.name,lead_phone:normPhone(s.phone),lead_city:s.city,lead_id:s.id}}];

const items = $input.all();
const blob = JSON.stringify(items);
const m = blob.match(/Existing ID:\s*(\d+)/);
if (m) { return [{ json: { existing_id: m[1] } }]; }

const stack = [...items];
while (stack.length) {
  const value = stack.shift();
  if (!value || typeof value !== 'object') { continue; }

  const ids = value.error?.context?.ids || value.context?.ids;
  if (Array.isArray(ids) && ids[0] != null) {
    return [{ json: { existing_id: String(ids[0]) } }];
  }

  if (typeof value.message === 'string') {
    const messageMatch = value.message.match(/(?:Existing ID|ID):\s*(\d+)/i);
    if (messageMatch) {
      return [{ json: { existing_id: messageMatch[1] } }];
    }
  }

  stack.push(...Object.values(value));
}

throw new Error('Conflict but no Existing ID: ' + blob.slice(0,300));

